update app.content_item_versions set stem='A polynomial function p has exactly 5 local extrema, and the graph of p rises without bound at both ends of the graph. What is the least possible degree of p?', canonical_answer_1='B' where id=(select v.id from app.content_item_versions v join app.content_items ci on ci.id=v.content_item_id where ci.content_key='apprecalc-mcq-b10-h-1.4-b' and ci.status='published' and v.status='published');
update app.mcq_choices set choice_text='5', is_correct=false, rationale='A polynomial of degree 5 has at most 4 turning points, but this function has 5. The degree must be at least 6.' where content_item_version_id=(select v.id from app.content_item_versions v join app.content_items ci on ci.id=v.content_item_id where ci.content_key='apprecalc-mcq-b10-h-1.4-b' and ci.status='published' and v.status='published') and choice_key='A';
update app.mcq_choices set choice_text='6', is_correct=true, rationale='Correct: A polynomial of degree n has at most n − 1 turning points, so n ≥ 6. Both ends rising means even degree, which also forces an odd number of turning points (5 is odd), so the least possible degree is 6.' where content_item_version_id=(select v.id from app.content_item_versions v join app.content_items ci on ci.id=v.content_item_id where ci.content_key='apprecalc-mcq-b10-h-1.4-b' and ci.status='published' and v.status='published') and choice_key='B';
update app.mcq_choices set choice_text='7', is_correct=false, rationale='A polynomial of degree 7 could have 5 turning points, but a degree-7 polynomial is odd, so its ends would point in opposite directions. The stated end behavior requires an even degree.' where content_item_version_id=(select v.id from app.content_item_versions v join app.content_items ci on ci.id=v.content_item_id where ci.content_key='apprecalc-mcq-b10-h-1.4-b' and ci.status='published' and v.status='published') and choice_key='C';
update app.mcq_choices set choice_text='4', is_correct=false, rationale='A polynomial of degree 4 has at most 3 turning points, but this function has 5. The degree must be at least 6.' where content_item_version_id=(select v.id from app.content_item_versions v join app.content_items ci on ci.id=v.content_item_id where ci.content_key='apprecalc-mcq-b10-h-1.4-b' and ci.status='published' and v.status='published') and choice_key='D';
update app.content_item_versions set stem='A polynomial function s has exactly 2 turning points, and the graph of s falls without bound to the left and rises without bound to the right. What is the least possible degree of s?', canonical_answer_1='A' where id=(select v.id from app.content_item_versions v join app.content_items ci on ci.id=v.content_item_id where ci.content_key='apprecalc-mcq-b10-sv-h-1.4-b-v3' and ci.status='published' and v.status='published');
update app.mcq_choices set choice_text='3', is_correct=true, rationale='Correct: A polynomial of degree n has at most n − 1 turning points, so n ≥ 3. The ends pointing opposite ways means odd degree, which also forces an even number of turning points (2 is even), so the least possible degree is 3.' where content_item_version_id=(select v.id from app.content_item_versions v join app.content_items ci on ci.id=v.content_item_id where ci.content_key='apprecalc-mcq-b10-sv-h-1.4-b-v3' and ci.status='published' and v.status='published') and choice_key='A';
update app.mcq_choices set choice_text='2', is_correct=false, rationale='A polynomial of degree 2 has at most 1 turning point, but this function has 2. The degree must be at least 3.' where content_item_version_id=(select v.id from app.content_item_versions v join app.content_items ci on ci.id=v.content_item_id where ci.content_key='apprecalc-mcq-b10-sv-h-1.4-b-v3' and ci.status='published' and v.status='published') and choice_key='B';
update app.mcq_choices set choice_text='4', is_correct=false, rationale='A polynomial of degree 4 could have 2 turning points, but a degree-4 polynomial is even, so its ends would point the same way. The stated end behavior requires an odd degree.' where content_item_version_id=(select v.id from app.content_item_versions v join app.content_items ci on ci.id=v.content_item_id where ci.content_key='apprecalc-mcq-b10-sv-h-1.4-b-v3' and ci.status='published' and v.status='published') and choice_key='C';
update app.mcq_choices set choice_text='1', is_correct=false, rationale='A polynomial of degree 1 has at most 0 turning points, but this function has 2. The degree must be at least 3.' where content_item_version_id=(select v.id from app.content_item_versions v join app.content_items ci on ci.id=v.content_item_id where ci.content_key='apprecalc-mcq-b10-sv-h-1.4-b-v3' and ci.status='published' and v.status='published') and choice_key='D';
insert into app.content_taxonomy_validation_decisions (validation_decision_id, content_taxonomy_label_id, decided_by, decision, decision_source, reviewed_primary_unit, reviewed_required_units, notes)
select gen_random_uuid(), l.content_taxonomy_label_id, 'f5a26c6b-3566-4d58-9e97-979fbb947564'::uuid, 'confirmed', 'chat_review', l.primary_unit, l.required_units,
 'Product Owner chat instruction 2026-11-12 ("Fix in place"): stem and choices corrected (turning-point counts contradicted the stated end behavior); topic and units unchanged, label re-confirmed.'
from app.content_taxonomy_labels l where l.label_scope='serving' and l.superseded_by is null and l.label_status='stale' and l.content_item_id in (select id from app.content_items where content_key in ('apprecalc-mcq-b10-h-1.4-b','apprecalc-mcq-b10-sv-h-1.4-b-v3'));
update app.content_taxonomy_labels l set label_status='validated', validated_by='f5a26c6b-3566-4d58-9e97-979fbb947564'::uuid, validated_at=now(), validation_decision_id=d.validation_decision_id,
 validated_against_version_id=(select v.id from app.content_item_versions v where v.content_item_id=l.content_item_id and v.status='published'),
 validated_against_taxo_hash=app.taxonomy_relevant_hash((select v.id from app.content_item_versions v where v.content_item_id=l.content_item_id and v.status='published'))
from app.content_taxonomy_validation_decisions d where d.content_taxonomy_label_id=l.content_taxonomy_label_id and d.notes like 'Product Owner chat instruction 2026-11-12 ("Fix in place")%' and l.label_scope='serving' and l.superseded_by is null and l.label_status='stale';
do $$ declare n int; m int; begin
 select count(*) into n from app.content_items ci join app.content_item_versions v on v.content_item_id=ci.id and v.status='published' join app.mcq_choices c on c.content_item_version_id=v.id where ci.content_key in ('apprecalc-mcq-b10-h-1.4-b','apprecalc-mcq-b10-sv-h-1.4-b-v3');
 if n<>8 then raise exception 'expected 8 choice rows, got %', n; end if;
 select count(*) into m from app.content_items ci join app.content_taxonomy_labels l on l.content_item_id=ci.id and l.label_scope='serving' and l.superseded_by is null and l.label_status='validated' join app.content_item_versions v on v.id=l.validated_against_version_id and l.validated_against_taxo_hash=app.taxonomy_relevant_hash(v.id) where ci.content_key in ('apprecalc-mcq-b10-h-1.4-b','apprecalc-mcq-b10-sv-h-1.4-b-v3');
 if m<>2 then raise exception 'serving labels valid for % of 2', m; end if;
end $$;
